<?php
use UPS\Onboarding;
use UPS\Service;
use UPS\App;
function installationBody(): array { return ['id'=>Service::uuid(),'agent_id'=>Service::uuid(),'name'=>'My UPS server','proof'=>bin2hex(random_bytes(32)),'code'=>'00123456','agent_token'=>Service::token('agent')]; }
function install(App $a,array $body,int $now): array { return $a->handle('POST','/installations','',$body,[],'pi',$now); }
function claimInstall(App $a,array $body,string $mobile,int $now): array { return $a->handle('POST','/installations/claim','',['id'=>$body['id'],'code'=>$body['code'],'mobile_token'=>$mobile,'consent'=>true],[],'phone',$now); }
test('installation creates no workspace or agent before phone consent',function(){[$a,$o,$n,$dir]=fixture();$body=installationBody();$count=countRows($a,'workspaces');$receipt=install($a,$body,$n);install($a,$body,$n+1);check($receipt['id']===$body['id']&&countRows($a,'workspaces')===$count&&countRows($a,'agents')===0,'installation provisioned before consent');$raw=file_get_contents($dir.'/monitor.sqlite');foreach(['proof','code','agent_token'] as $key){check(!str_contains($raw,$body[$key]),'raw installation secret stored');}$s=$a->handle('POST','/installations/status','',['id'=>$body['id'],'proof'=>$body['proof']],[],'pi',$n);check(!$s['linked'],'unclaimed installation active');});
test('installation code claims one private workspace with retry-safe mobile access',function(){[$a,$o,$n,$dir]=fixture();$body=installationBody();install($a,$body,$n);$token=Service::token('mobile');$receipt=claimInstall($a,$body,$token,$n);$retry=claimInstall($a,$body,$token,$n+1);check($receipt['session_id']===$retry['session_id']&&countRows($a,'mobile_sessions')===1,'retry duplicated mobile access');$state=$a->handle('POST','/installations/status','',['id'=>$body['id'],'proof'=>$body['proof']],[],'pi',$n);check($state['linked']&&$state['agent_id']===$body['agent_id']&&!isset($state['access_token']),'agent status leaks phone credentials');$agents=$a->handle('GET','/agents',$token,[],[],'phone',$n)['agents'];check(count($agents)===1&&$agents[0]['id']===$body['agent_id'],'phone not scoped');$p=packet($body['agent_id'],1,$n);upload($a,$body,$p,$n);check(count($a->handle('GET','/agents/'.$body['agent_id'].'/state',$token,[],[],'phone',$n)['devices'])===1,'agent token cannot report');fails(401,fn()=>claimInstall($a,$body,Service::token('mobile'),$n));check(!str_contains(file_get_contents($dir.'/monitor.sqlite'),$token),'mobile token stored in database');});
test('installation rejects missing consent expiry and public identity takeovers',function(){[$a,$o,$n]=fixture();$body=installationBody();install($a,$body,$n);fails(422,fn()=>$a->handle('POST','/installations/claim','',['id'=>$body['id'],'code'=>$body['code'],'mobile_token'=>Service::token('mobile'),'consent'=>false],[],'phone',$n));$bad=$body;$bad['proof']=bin2hex(random_bytes(32));fails(409,fn()=>install($a,$bad,$n));fails(401,fn()=>$a->handle('POST','/installations/status','',['id'=>$body['id'],'proof'=>$bad['proof']],[],'pi',$n));fails(401,fn()=>claimInstall($a,$body,Service::token('mobile'),$n+1801));$agent=paired($a,$o['owner_token'],$n);$body=installationBody();$body['agent_id']=$agent['agent_id'];fails(409,fn()=>install($a,$body,$n));});
test('installation code is locked after five guesses across peers',function(){[$a,$o,$n]=fixture();$body=installationBody();install($a,$body,$n);for($i=0;$i<5;$i++){fails(401,fn()=>$a->handle('POST','/installations/claim','',['id'=>$body['id'],'code'=>'99999999','mobile_token'=>Service::token('mobile'),'consent'=>true],[],'peer-'.$i,$n));}fails(401,fn()=>claimInstall($a,$body,Service::token('mobile'),$n));check(countRows($a,'agents')===0,'locked installation created agent');});
test('schema three upgrades with backup and keeps existing readings',function(){[$a,$o,$n,$dir]=fixture();$agent=paired($a,$o['owner_token'],$n);upload($a,$agent,packet($agent['agent_id'],1,$n),$n);unset($a);$db=new PDO('sqlite:'.$dir.'/monitor.sqlite');$db->exec('DROP TABLE workspace_managers; DROP TABLE enrollments; PRAGMA user_version=3');unset($db);unlink($dir.'/monitor-before-v4.sqlite');$a=new App(['storage_dir'=>$dir,'public_url'=>'https://ups.example/api/v1']);check(is_file($dir.'/monitor-before-v4.sqlite'),'no schema four backup');check(count(state($a,$o,$agent,$n)['devices'])===1,'existing reading lost');});

test('only the installation creator may invite phones and delete remote data',function(){[$a,$o,$n]=fixture();$body=installationBody();install($a,$body,$n);$token=Service::token('mobile');$receipt=claimInstall($a,$body,$token,$n);check($a->handle('GET','/workspace-management',$token,[],[],'phone',$n)['can_manage'],'creator cannot manage data');$code=$a->handle('POST','/mobile-pairings',$token,[],[],'phone',$n);$other=$a->handle('POST','/mobile-pairings/claim','',['code'=>$code['pairing_code']],[],'second',$n);fails(403,fn()=>$a->handle('DELETE','/workspace',$other['access_token'],[],[],'second',$n));$a->handle('DELETE','/workspace',$token,[],[],'phone',$n);check(countRows($a,'enrollments')===0,'installation secrets remain after deletion');fails(401,fn()=>$a->handle('GET','/agents',$token,[],[],'phone',$n));});

test('server operator can recover phone access without replacing agent credentials',function(){[$a,$o,$n]=fixture();$first=installationBody();install($a,$first,$n);$token=Service::token('mobile');$owner=claimInstall($a,$first,$token,$n);$next=installationBody();$next['agent_id']=$first['agent_id'];$next['agent_token']=$first['agent_token'];install($a,$next,$n+60);$recovered=claimInstall($a,$next,Service::token('mobile'),$n+60);check($recovered['workspace_id']===$owner['workspace_id']&&countRows($a,'agents')===1,'recovery replaced agent or space');check($a->handle('GET','/workspace-management',$token,[],[],'old-phone',$n+60)['can_manage'],'recovery removed previous owner');upload($a,$first,packet($first['agent_id'],1,$n+60),$n+60);check(count($a->handle('GET','/agents',$recovered['access_token'],[],[],'recovered',$n+60)['agents'])===1,'recovered phone has no access');});
